// Zweck: Status-Meldung eines Master-Geräts (Gateway) verarbeiten.
// Eingaben:
//   msg.sh      – Routing-State aus dem Ingest-Tab (scope='master', topic_type='status')
//   msg.payload – Status-Payload mit online, wifi, mqtt, espnow, fw
// Ausgaben:
//   msg.payload      – aktualisiertes Master-Objekt
//   msg.sqlite_batch – SQL-Batch für die Persistenzschicht
// Seiteneffekt:
//   smarthome_runtime (global) wird mit dem aktualisierten Master-Eintrag überschrieben.

const topicHandlers = global.get("topicHandlers");

// Sicherheitscheck: Lib-Helper müssen vorhanden sein.
if (!topicHandlers || typeof topicHandlers.handleRoutedMessage !== "function") {
    node.error("topicHandlers fehlt – Boot-Flow prüfen (00_boot)", msg);
    return null;
}

const result = topicHandlers.handleRoutedMessage(
    global.get("smarthome_runtime"),
    msg.sh,
    msg.payload
);

// Wenn kein Master erkannt wurde, Nachricht verwerfen.
if (!result || !result.payload || !result.payload.master) {
    node.warn("master status: Master-ID fehlt im Payload");
    return null;
}

// Aktualisierten Runtime-State zurückschreiben.
global.set("smarthome_runtime", result.runtime);

msg.payload      = result.payload;
msg.sqlite_batch = result.sqlite_batch || null;
return msg;
